INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(2101, 'Exodus 23:25', 'Exodus', 23, 25, '&nbsp;کۀ تاسو زما، مالِک خُدائ د ستاسو خُدائ پاک عبادت کوئ، نو زۀ به ستاسو په خوراک او اوبو کښې برکت واچوم او د ټولو بيماريانو نه به مو بچ وساتم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2102, 'Exodus 23:26', 'Exodus', 23, 26, '&nbsp;ستاسو په مُلک کښې به د يوې ښځې هم بچى نۀ ضائع کيږى او يوه ښځه به هم شنډه نۀ وى. زۀ به تاسو له اوږد عُمر درکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2103, 'Exodus 23:27', 'Exodus', 23, 27, '&nbsp;زۀ به په هغه خلقو خپله يره راولم چې کوم ستاسو مخالفت کوى، زۀ به هغه خلق په وارخطايۍ آخته کړم د کومو خلقو سره چې تاسو جنګ کوئ او زۀ به ستاسو ټول دشمنان ستاسو نه وزغلوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2104, 'Exodus 23:28', 'Exodus', 23, 28, '&nbsp;زۀ به ستاسو په دشمنانو وارخطائى راولم، چې تاسو مخ په وړاندې ځئ نو زۀ به حِويان، کنعانيان او حِتيان ستاسو د مخې نۀ لرې کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2105, 'Exodus 23:29', 'Exodus', 23, 29, '&nbsp;زۀ به هغوئ په يو کال کښې نۀ وباسم، کۀ ما داسې وکړل، نو زمکه به ويجاړه شى او هلته به ډېر زيات ځنګلى ځناور وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2106, 'Exodus 23:30', 'Exodus', 23, 30, '&nbsp;خو زۀ به هغوئ ورو ورو وباسم، تر دې پورې چې تاسو زيات شئ او هغه زمکه ستاسو خپله شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2107, 'Exodus 23:31', 'Exodus', 23, 31, '&nbsp;زۀ به ستاسو د زمکې سرحدونه د بحرِقُلزم نه واخله د مديترانى د سمندر پورې او د بيابان نه د فرات سيند پورې خوارۀ کړم. زۀ به د هغې زمکې اوسېدونکى ستاسو په لاس کښې درکړم او چې تاسو مخ په وړاندې ځئ نو هغوئ به وشړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2108, 'Exodus 23:32', 'Exodus', 23, 32, '&nbsp;د هغوئ يا د هغوئ د معبودانو سره لوظ مۀ کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2109, 'Exodus 23:33', 'Exodus', 23, 33, '&nbsp;هغوئ خپل مُلک کښې اوسېدو ته مۀ پرېږدئ، کۀ تاسو پرېښودل نو هغوئ به تاسو دوکه کړى او زما خِلاف ګناه کولو ته به مو جوړ کړى. کۀ تاسو د هغوئ د معبودانو عبادت وکړئ نو دا به ستاسو دپاره يو دام جوړ شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2110, 'Exodus 24:1', 'Exodus', 24, 1, '&nbsp;مالِک خُدائ موسىٰ ته وفرمائيل چې، ”ما ته تۀ، هارون، ندب، ابيهُو او د بنى اِسرائيلو اويا مشران بره غر ته راشئ، خو نزدې مۀ راځئ او د لرې نه ما ته سجده وکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2111, 'Exodus 24:2', 'Exodus', 24, 2, '&nbsp;صِرف تۀ ما له راشه او هغه نور به ما له نزدې نۀ راځى. نور کسان به تا سره غرۀ ته نۀ راخېژى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2112, 'Exodus 24:3', 'Exodus', 24, 3, '&nbsp;موسىٰ راغلو او خلقو ته يې د مالِک خُدائ ټولې خبرې او ټول اصُول بيان کړل او ټولو خلقو په يو آواز جواب ورکړو، ”څنګه چې مالِک خُدائ فرمائيلى دى نو مونږ به هم هغه شان کوُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2113, 'Exodus 24:4', 'Exodus', 24, 4, '&nbsp;موسىٰ د مالِک خُدائ هغه ټولې خبرې وليکلې. بل سحر وختى د غرۀ په لمن کښې هغۀ يوه قربان‌ګاه جوړه کړه او د بنى اِسرائيلو د دولسو قبيلو په مطابق يې د هرې يوې دپاره دولس تيږې ودرولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2114, 'Exodus 24:5', 'Exodus', 24, 5, '&nbsp;بيا هغۀ د بنى اِسرائيلو څۀ زلمى مقرر کړل او هغوئ مالِک خُدائ ته سوزېدونکې قربانۍ او څۀ څاروى د سلامتۍ قربانۍ په توګه پېش کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2115, 'Exodus 24:6', 'Exodus', 24, 6, '&nbsp;موسىٰ د ځناورو هغه نيمه وينه واخستله او په ښانکونو کښې يې واچوله، او هغه نوره نيمه يې په قربان‌ګاه وشيندله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2116, 'Exodus 24:7', 'Exodus', 24, 7, '&nbsp;بيا هغۀ د لوظ کِتاب راواخستلو او حاضرو خلقو ته يې واورولو. هغوئ ووئيل، ”مونږ به د مالِک خُدائ تابعدارى کوُو او د هغۀ په ټولو خبرو به عمل کوُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2117, 'Exodus 24:8', 'Exodus', 24, 8, '&nbsp;بيا موسىٰ هغه وينه راواخستله چې په ښانکونو کښې وه او په خلقو يې وشيندله. هغۀ وفرمائيل، ”ګورئ، دا وينه د لوظ د پوخوالى دپاره ده کوم چې مالِک خُدائ تاسو سره کړے دے چې کله هغۀ دا ټول حُکمونه درکول.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2118, 'Exodus 24:9', 'Exodus', 24, 9, '&nbsp;موسىٰ، هارون، ندب، ابيهُو او د بنى اِسرائيلو هغه اويا مشران غرۀ ته وختل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2119, 'Exodus 24:10', 'Exodus', 24, 10, '&nbsp;او هغه د بنى اِسرائيلو خُدائ پاک يې وليدلو. د هغۀ د پښو لاندې لکه د آسمان په شان د نيلم کاڼى شين فرش وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2120, 'Exodus 24:11', 'Exodus', 24, 11, '&nbsp;د خُدائ پاک د لاس نه د بنى اِسرائيلو هغه مشرانو ته ضرر ونۀ رسېدلو، هغوئ خُدائ پاک وليدلو او بيا هغوئ خوراک څښاک وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2121, 'Exodus 24:12', 'Exodus', 24, 12, '&nbsp;مالِک خُدائ موسىٰ ته وفرمائيل، ”ما له غرۀ ته راوخېژه او چې کله تۀ هلته يې نو زۀ به تا له د کاڼو دوه تختې درکړم چې په هغې باندې ما ټول اصُول او حُکمونه ليکلى دى چې تۀ به دا خلقو ته بيانوې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2122, 'Exodus 24:13', 'Exodus', 24, 13, '&nbsp;موسىٰ د خپل مدد کوونکى يشوَع سره روان شو او موسىٰ د خُدائ پاک غرۀ ته بره ختلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2123, 'Exodus 24:14', 'Exodus', 24, 14, '&nbsp;موسىٰ مشرانو ته وفرمائيل، ”تاسو مونږ ته دلته تر هغې پورې اِنتظار کوئ چې مونږ واپس نۀ يُو راغلى. هارون او حُور به ستاسو سره وى، او کۀ د چا څۀ لانجه وى نو هغوئ له دې ورځى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2124, 'Exodus 24:15', 'Exodus', 24, 15, '&nbsp;چې موسىٰ بره وختلو نو وريځې غر پټ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2125, 'Exodus 24:18', 'Exodus', 24, 18, '&nbsp;چې موسىٰ بره غرۀ ته ورختلو نو د وريځې مينځ ته ورننوتلو او څلوېښت ورځې او څلوېښت شپې په غرۀ کښې ايسار شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2126, 'Exodus 25:1', 'Exodus', 25, 1, '&nbsp;مالِک خُدائ موسىٰ ته وفرمائيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2127, 'Exodus 25:2', 'Exodus', 25, 2, '&nbsp;”بنى اِسرائيلو ته ووايه چې ما ته يوه نذرانه پېش کړى. چې څوک د زړۀ نه ما ته څۀ نذرانه پېش کول غواړى تۀ يې ترې نه اخله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2128, 'Exodus 25:3', 'Exodus', 25, 3, '&nbsp;دا هغه نذرانې دى چې کومې به ترې نه تۀ اخلې، سرۀ زر، سپين زر او زېړ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2129, 'Exodus 25:4', 'Exodus', 25, 4, '&nbsp;کتان، د آسمانى رنګ، کاسنى او د سور رنګ وړۍ، د چېلو د وړۍ کپړه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2130, 'Exodus 25:5', 'Exodus', 25, 5, '&nbsp;سره رنګ شوې د ګډو څرمن، ښۀ څرمن، د کيکر لرګے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2131, 'Exodus 25:6', 'Exodus', 25, 6, '&nbsp;د ډيوو دپاره تېل، د غوړولو د تېلو دپاره مصالحې او د خوشبويۍ مصالحې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2132, 'Exodus 25:7', 'Exodus', 25, 7, '&nbsp;اونيکس کاڼى او نور قيمتى کاڼى چې د مشر اِمام په مقدس واسکټ باندې چې پېش بند ورته وائى او د هغۀ د سينې جېب باندې ولګولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2133, 'Exodus 25:8', 'Exodus', 25, 8, '&nbsp;او خلق به زما دپاره يوه مقدسه خېمه جوړه کړى، نو زۀ به د هغوئ په مينځ کښې اوسېږم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2134, 'Exodus 25:9', 'Exodus', 25, 9, '&nbsp;دا مقدسه خېمه او د هغې ټول سامان د هغې نقشې په مطابق جوړ کړئ کومه چې زۀ درته ښايم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2135, 'Exodus 25:10', 'Exodus', 25, 10, '&nbsp;هغوئ به زما دپاره د کيکر د لرګى نه يو صندوق جوړ کړى، چې پينځۀ څلوېښت اِنچه اوږد وى، اوويشت اِنچه پلن او اوويشت اِنچه لوړ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2136, 'Exodus 25:11', 'Exodus', 25, 11, '&nbsp;دننه او بهر ورباندې د سوچه سرو زرو پترے وخېژوه او د دې د سر نه ګېرچاپېره د سرو زرو غاړه تاو کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2137, 'Exodus 25:12', 'Exodus', 25, 12, '&nbsp;د وړلو دپاره ورله د سرو زرو څلور ګول کَړۍ جوړې کړه او دا ورله په څلورو پښو پورې ولګوه، چې دوه کَړۍ يو خوا وى او دوه بل خوا وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2138, 'Exodus 25:13', 'Exodus', 25, 13, '&nbsp;د وړلو دپاره ورله د کيکر لرګى نه بازوګان جوړ کړه او د سرو زرو پترى ورباندې وخېژوه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2139, 'Exodus 25:14', 'Exodus', 25, 14, '&nbsp;او دا بازوګان د صندوق د وړولو دپاره په کړو کښې دواړو طرفونو ته وردننه کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2140, 'Exodus 25:15', 'Exodus', 25, 15, '&nbsp;هغه بازوګان به په هغه کړو کښې پرېږدئ او وباسئ به يې ترېنه نه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2141, 'Exodus 25:16', 'Exodus', 25, 16, '&nbsp;بيا د لوظ صندوق کښې هغه د کاڼو دوه تختې کېږده کومې چې زۀ درکوم، په کومو باندې چې حُکمونه ليکلى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2142, 'Exodus 25:17', 'Exodus', 25, 17, '&nbsp;د سوچه سرو زرو يو سر ورله جوړ کړه چرته به چې کفاره ادا کيږى، چې پينځۀ څلوېښت اِنچه اوږد وى او اوويشت اِنچه پلن وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2143, 'Exodus 25:18', 'Exodus', 25, 18, '&nbsp;د ټکېدلے شوو سرو زرو نه دوه د وزرو والا مخلوق ورله جوړ کړه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2144, 'Exodus 25:19', 'Exodus', 25, 19, '&nbsp;يو ورباندې په يو سر کښې او بل په بل سر کښې جوړ کړه نو چې دواړه د لوظ صندوق د کفارې د سر سره يوه ټُکړه شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2145, 'Exodus 25:20', 'Exodus', 25, 20, '&nbsp;د وزرو والا مخلوق دې د لوظ صندوق د کفارې په تخت باندې يو بل ته مخامخ وى او د هغوئ خورې وزرې دې د صندوق د کفارې تخت پټ کړى او مخونه به يې لاندې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2146, 'Exodus 25:21', 'Exodus', 25, 21, '&nbsp;د کاڼى چې کومې دوه تختې زۀ درکوم هغه د لوظ صندوق کښې کېږده او هغه د کفارې تخت د صندوق دپاسه کېږده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2147, 'Exodus 25:22', 'Exodus', 25, 22, '&nbsp;زۀ به تا سره هلته ملاقات وکړم او د دې دوو وزرو والا مخلوق په مينځ کښې چې د کفارې صندوق د سر دپاسه دى زۀ به تا له د اِسرائيلو دپاره خپل حُکمونه درکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2148, 'Exodus 25:23', 'Exodus', 25, 23, '&nbsp;د کيکر لرګى نه يو مېز جوړ کړه، چې شپږ دېرش اِنچه اوږد وى، اتلس اِنچه پلن او اوويشت اِنچه لوړ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2149, 'Exodus 25:24', 'Exodus', 25, 24, '&nbsp;په دې د سوچه سرو زرو پترے وخېژوه او د دې نه ګېرچاپېره د سرو زرو غاړه تاو کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2150, 'Exodus 25:25', 'Exodus', 25, 25, '&nbsp;ګېرچاپېره درې اِنچه پلنه يوه ژۍ ورله جوړه کړه او ژۍ نه ګېرچاپېره د سرو زرو غاړه تاو کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2151, 'Exodus 25:26', 'Exodus', 25, 26, '&nbsp;د دې وړلو دپاره د سرو زرو څلور ګول کَړۍ جوړې کړه او دا په هغه څلورو ګوټونو کښې ولګوه، چرته چې پښې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2152, 'Exodus 25:27', 'Exodus', 25, 27, '&nbsp;دا کَړۍ به د ژۍ سره نزدې ولګولے شى چې هغه بازوګان ونيسى چې د کومو په ذريعه دا مېز وړلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2153, 'Exodus 25:28', 'Exodus', 25, 28, '&nbsp;دا بازوګان د کيکر لرګى نه جوړ کړه او په دې باندې د سرو زرو پترى وخېژوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2154, 'Exodus 25:29', 'Exodus', 25, 29, '&nbsp;د سوچه سرو زرو نه رکېبۍ او لوښى جوړ کړه او دغه شان د نذرانو تويَولو دپاره منګى او جامونه هم جوړ کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
