(2156, 'Exodus 25:31', 'Exodus', 25, 31, '&nbsp;د سوچه سرو زرو نه يو ډيوټ جوړ کړه. د دې بېخ او د دې ډنډا د ټکېدلے شوو سرو زرو نه جوړ کړه، د دې د ښۀ ښکارېدلو دپاره ګلونه، سره د غوټو او پاڼو جوړ کړه، چې د دې سره يوه ټُکړه شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2157, 'Exodus 25:32', 'Exodus', 25, 32, '&nbsp;د ډيوټ د اړخونو نه دې شپږ څانګې وتلې وى، چې درې په يو طرف وى او درې په بل طرف وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2158, 'Exodus 25:33', 'Exodus', 25, 33, '&nbsp;د دې شپږ واړو څانګو به درې درې د ښۀ ښکارېدو ګلونه وى، دا به سره د غوټو او پاڼو د بادام د ګلونو په شان جوړ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2159, 'Exodus 25:34', 'Exodus', 25, 34, '&nbsp;د ډيوټ د ډنډې به د ښۀ ښکارېدو څلور ګلونه وى، دا به سره د غوټو او د پاڼو د بادام د ګلونو په شان وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2160, 'Exodus 25:35', 'Exodus', 25, 35, '&nbsp;د دې درېو واړو څانګو د هرې يوې لاندې به يوه غوټۍ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2161, 'Exodus 25:36', 'Exodus', 25, 36, '&nbsp;دا غوټۍ، څانګې او دا ډيوټ به د ټکېدلے شوو سوچه سرو زرو د يوې ټُکړې نه جوړ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
