(2165, 'Exodus 25:40', 'Exodus', 25, 40, '&nbsp;ګوره چې دا د هغې نقشې په مطابق جوړ کړې چې کومه ما درته په غرۀ باندې ښودلې ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2166, 'Exodus 26:1', 'Exodus', 26, 1, '&nbsp;او مالِک خُدائ وفرمائيل، ”د مقدسې خېمې يعنې زما د حضور خېمې دننه برخه د کتان د لسو پړدو نه جوړه کړه چې دا د آسمانى رنګ، کاسنى او د سور رنګ د وړۍ نه تياره وى. په دې باندې په ګُلکارۍ کښې د وزرو والا مخلوق جوړ کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2167, 'Exodus 26:2', 'Exodus', 26, 2, '&nbsp;هره يوه پړده په برابر ناپ جوړه کړه چې څوارلس ګزه اوږده وى او دوه ګزه پلنه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2168, 'Exodus 26:3', 'Exodus', 26, 3, '&nbsp;پينځۀ پړدې په يو ځائ وګنډه. او هغه نورې پينځۀ پړدې هم په يو ځائ وګنډه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2169, 'Exodus 26:4', 'Exodus', 26, 4, '&nbsp;په هره يوه جوړه کښې، د پړدې په بهرنۍ غاړه د آسمانى رنګ د کپړې کَړۍ جوړې کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2170, 'Exodus 26:5', 'Exodus', 26, 5, '&nbsp;د وړومبۍ جوړې په وړومبۍ پړده پنځوس کَړۍ او پنځوس کَړۍ د دوېمې جوړې په آخرى پړده جوړې کړه چې دا کَړۍ يو بل ته مخامخ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
