(2173, 'Exodus 26:8', 'Exodus', 26, 8, '&nbsp;دا ټولې په يو ناپ جوړې کړه، چې پينځلس ګزه اوږدې او دوه ګزه پلنې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2174, 'Exodus 26:9', 'Exodus', 26, 9, '&nbsp;پينځۀ پړدې په يو ځائ وګنډه او هغه نورې شپږ هم يو ځائ وګنډه. شپږمه پړده د خېمې په مخکښېنۍ حِصه باندې غبرګه کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2175, 'Exodus 26:10', 'Exodus', 26, 10, '&nbsp;د يوې جوړې د آخرى پړدې په غاړه پنځوس کَړۍ جوړې کړه او د هغه بلې جوړې په غاړه هم پنځوس کَړۍ جوړې کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
